package com.emotiondiary.security;
import com.emotiondiary.service.AuthService;import jakarta.servlet.*;import jakarta.servlet.http.*;import org.springframework.beans.factory.annotation.*;import org.springframework.context.annotation.*;import org.springframework.http.HttpHeaders;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.config.http.SessionCreationPolicy;import org.springframework.security.core.authority.AuthorityUtils;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.security.web.*;import org.springframework.web.cors.*;import java.io.IOException;import java.util.List;
@Configuration public class SecurityConfig { @Autowired JwtService jwt; @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();}
@Bean SecurityFilterChain filterChain(HttpSecurity http,@Value("${app.cors-origin}") String origin)throws Exception{return http.csrf(c->c.disable()).cors(c->c.configurationSource(r->{var cfg=new CorsConfiguration();cfg.setAllowedOrigins(List.of(origin));cfg.setAllowedMethods(List.of("*"));cfg.setAllowedHeaders(List.of("*"));return cfg;})).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/api/auth/**").permitAll().anyRequest().authenticated()).addFilterBefore(new OncePerRequestFilter(){@Override protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{var h=req.getHeader(HttpHeaders.AUTHORIZATION); if(h!=null&&h.startsWith("Bearer ")){ try{var c=jwt.parse(h.substring(7)); var auth=new UsernamePasswordAuthenticationToken(c.getSubject(),null,AuthorityUtils.NO_AUTHORITIES); SecurityContextHolder.getContext().setAuthentication(auth);}catch(Exception ignored){}} chain.doFilter(req,res);} }, UsernamePasswordAuthenticationFilter.class).build(); }
}
